// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ProjectData {
  _id: string;
  projectName: string;
  projectType: string;
  status: string;
  hourlyRate: number;
  completionPct: number;
  totalDeliverables: number;
  completedDeliverables: number;
  teamMembers: { name: string; email: string; role: string; title: string }[];
  lastActivity: number;
  createdAt: number;
  milestones: { name: string; status: string }[];
}

interface ProposalData {
  _id: string;
  title: string;
  status: string;
  totalValue: number;
  currency: string;
  publicToken: string;
  createdAt: number;
  sentAt?: number;
  viewedAt?: number;
  signedAt?: number;
  validUntil?: number;
  sections: any[];
}

interface InvoiceData {
  _id: string;
  invoiceNumber: string;
  status: string;
  issueDate: number;
  dueDate: number;
  paidDate?: number;
  clientName?: string;
  lineItems: any[];
  subtotal: number;
  taxRate?: number;
  taxAmount?: number;
  total: number;
  currency: string;
  notes?: string;
  proofCount?: number;
  hasValidatedBilling?: boolean;
  workProofs: any[];
  createdAt: number;
}

interface TeamMember {
  name: string;
  email: string;
  role: string;
  title: string;
  projects: string[];
}

